-- Nothing left unsaid: the storyboard's meaning exists for every column.
do $$
declare
  empty int;
begin
  select count(*) into empty from public.steps where coalesce(summary, '') = '';
  if empty <> 0 then
    raise exception 'step fill: % steps still have no summary', empty;
  end if;
end $$;

commit;
